"""undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused
from binkeep.report import entry_lines

STOCK_OPS = journal.OPS


def _broken(msg):
    return DataError("journal", msg)


def scan(entries):
    """Returns (done, undone, status, last_undo): stacks hold operation entries."""
    done, undone, status, last_undo = [], [], {}, {}
    for i, e in enumerate(entries):
        op = e["op"]
        if op in STOCK_OPS:
            for u in undone:
                status[id(u)] = "dropped"
            undone.clear()
            done.append(e)
        elif op == "undo":
            if not done or done[-1]["seq"] != e.get("target"):
                raise _broken(f"seq {e['seq']}: undo does not match")
            t = done.pop()
            undone.append(t)
            last_undo[id(t)] = e
        elif op == "redo":
            if not undone or undone[-1]["seq"] != e.get("target"):
                raise _broken(f"seq {e['seq']}: redo does not match")
            done.append(undone.pop())
    return done, undone, last_undo


def _units(ctx, e):
    q = e["qty"]
    if e.get("uom") == "pk":
        item = ctx.items.get(e["sku"])
        if item is None:
            raise Refused("unknown-sku", f"no item {e['sku']}")
        q *= item.pack_size
    return q


def _plan_undo(ctx, e):
    """List of (bin, delta-or-None, absolute-or-None) steps, in order."""
    op = e["op"]
    if op == "fix":
        raise Refused("barrier", "a fix cannot be undone")
    if e.get("v") == 2:
        return [("set", f["bin"], f["before"]) for f in reversed(e["effects"])]
    if op == "count":
        raise Refused("irreversible", "the quantity before the count is unknown")
    if op == "receive":
        return [("add", normalize(e["bin"]), -_units(ctx, e))]
    if op == "issue":
        return [("add", normalize(b), q) for b, q in reversed(e["picks"])]
    if op == "move":
        return [("add", normalize(e["to"]), -e["qty"]), ("add", normalize(e["from"]), e["qty"])]
    raise _broken(f"seq {e['seq']}: unknown operation")


def run(ctx, kind, steps):
    entries = list(ctx.entries)
    done, undone, last_undo = scan(entries)
    store = ctx.store.copy()
    new, lines = [], []
    for _ in range(steps):
        if kind == "undo":
            if not done:
                raise Refused("nothing-to-undo", "nothing to undo")
            target = done[-1]
            plan = _plan_undo(ctx, target)
        else:
            if not undone:
                raise Refused("nothing-to-redo", "nothing to redo")
            target = undone[-1]
            u = last_undo[id(target)]
            plan = [("set", f["bin"], f["before"]) for f in reversed(u["effects"])]
        sku = target["sku"]
        effects = []
        for how, code, v in plan:
            if code not in ctx.bins:
                raise Refused("unknown-bin", f"no bin {code}")
            before = store.qty(sku, code)
            after = v if how == "set" else before + v
            store.restore(sku, code, after)
            effects.append({"bin": code, "before": before, "after": after})
        seq = journal.next_seq(entries)
        line = journal.entry(seq, kind, ctx.by, sku, target=target["seq"], effects=effects)
        entries.append(line)
        new.append(line)
        if kind == "undo":
            done.pop()
            undone.append(target)
        else:
            undone.pop()
            done.append(target)
        lines.append(f"#{seq} {kind} {sku} (#{target['seq']} {target['op']})")
        lines += entry_lines(line)[1:]
    ctx.commit(store, new)
    return lines


def history(ctx, limit):
    entries = ctx.entries
    done, undone, _ = scan(entries)
    in_done = {id(e) for e in done}
    in_undone = {id(e) for e in undone}
    # dropped: undone at some point but on neither stack as undone
    out = []
    for e in reversed([e for e in entries if e["op"] in STOCK_OPS]):
        if id(e) in in_undone:
            st = "undone"
        elif id(e) in in_done:
            st = "barrier" if e["op"] == "fix" else "done"
        else:
            st = "dropped"
        out.append(f"{e['seq']:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {st}")
        if len(out) == limit:
            break
    return out
